begin isolation level repeatable read read only;
      select jsonb_build_object('tables',(select jsonb_agg(jsonb_build_object(
        'relation',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,
        'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
          'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum)
          from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
          where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
        'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',x.conname,'definition',pg_get_constraintdef(x.oid)) order by x.conname),'[]') from pg_constraint x where x.conrelid=c.oid),
        'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'roles',p.polroles,
          'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname),'[]') from pg_policy p where p.polrelid=c.oid),
        'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),
          'function_definition',pg_get_functiondef(t.tgfoid)) order by t.tgname),'[]') from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),
        'api_grants',(select jsonb_object_agg(role_name,jsonb_build_object('select',has_table_privilege(role_name,c.oid,'SELECT'),
          'insert',has_table_privilege(role_name,c.oid,'INSERT'),'update',has_table_privilege(role_name,c.oid,'UPDATE'),
          'delete',has_table_privilege(role_name,c.oid,'DELETE'))) from unnest(array['anon','authenticated','service_role']) role_name)
        ) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace
        where n.nspname||'.'||c.relname in ('public.brand_entities','public.support_channels','public.payment_entrypoints','public.feature_flags','public.system_settings','public.admin_navigation_items','public.admin_queue_specs','public.admin_queue_filter_options','public.admin_queue_signals','public.admin_queue_sla_policies','public.notification_channels','public.notification_event_types','public.notification_templates','public.notification_template_versions','public.policy_documents','public.policy_document_sections','public.account_request_reason_options','public.collection_type_catalog','public.collection_category_subtypes','public.collection_purpose_templates','public.collection_type_country_rules','public.notification_preferences','collect_hybrid.sms_receipt_policies','collect_hybrid.sms_receipt_member_consents','collect_security.otp_policy','collect_hybrid.roster_resource_policy') and c.relkind='r'),
        'routines',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),
          'security_definer',p.prosecdef,'definition',pg_get_functiondef(p.oid),
          'api_execute',(select jsonb_object_agg(role_name,has_function_privilege(role_name,p.oid,'EXECUTE')) from unnest(array['anon','authenticated','service_role']) role_name)
          ) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
          where n.nspname in ('public','collect_hybrid','collect_security') and p.proname in ('get_public_runtime_config','admin_runtime_config','get_notification_runtime_config','get_active_policy_document','get_account_request_reason_options','admin_list_feature_flags','admin_list_settings','admin_set_feature_flag','admin_set_sms_receipt_policy','admin_set_sms_receipt_member_consent','configure_notification_dispatch_schedule','_notification_dispatch_configuration','audit_public_runtime_config_change','audit_policy_runtime_change','record_policy_acceptance','reserve_roster_resources','reserve_signed_otp_send','begin_signed_otp_send','render_notification_template','runtime_control_spec','runtime_control_hash','runtime_control_identity','runtime_control_actor','runtime_control_validate','runtime_control_check_values','runtime_control_guard','guard_runtime_control_events','admin_get_runtime_control_v1','admin_update_runtime_control_v1','admin_list_runtime_control_events_v1','update_notification_preferences')),
        'control_contracts',(select jsonb_object_agg(family,collect_security.runtime_control_spec(family))
          from unnest(array['account_request_reason_options','admin_navigation_items','admin_queue_filter_options','admin_queue_signals','admin_queue_sla_policies','admin_queue_specs','brand_entities','collection_category_subtypes','collection_purpose_templates','collection_type_catalog','collection_type_country_rules','feature_flags','notification_channels','notification_event_types','notification_preferences','notification_template_versions','notification_templates','otp_policy','payment_entrypoints','policy_document_sections','policy_documents','roster_resource_policy','sms_receipt_member_consents','sms_receipt_policies','support_channels','system_settings']::text[]) family));
      rollback;